/* Local lightweight highlight.js-compatible shim for offline deployments. */
(function (global) {
  'use strict';

  function escapeHtml(input) {
    return String(input)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/\"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  var hljs = {
    highlightElement: function () {
      /* no-op shim */
    },
    highlight: function (code) {
      return { value: escapeHtml(code) };
    }
  };

  global.hljs = global.hljs || hljs;
})(typeof window !== 'undefined' ? window : globalThis);
